              "lowMinutes": 15,
              "likelyMinutes": 20,
              "highMinutes": 30
            },
            "timeboxMinutes": 30,
            "commitment": {
              "category": "CONTINGENT",
              "trigger": {
                "checkpointActivityId": "ohm_series_solve",
                "condition": "Your unassisted changed-circuit attempt in ohm_series_solve is incorrect (wrong current, a wrong voltage drop, or drops that do not sum to the source voltage) or you cannot justify the steps in your own words."
              }
            },
